```javascript
const sortObjByKeys = (obj, keys) => {
  const sortedKeys = keys.slice().sort();
  return Object.fromEntries(
    Array.from(Object.entries(obj), (([key, value]) => [sortedKeys[keys.indexOf(key)], value]))
  );
};

// Example usage:
