 Here's the implementation of the `smart_sort_array` function in PHP:

```php
function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];

        if (intval($ageA) === intval($ageB)) {
            // Sort by name if ages are equal
            return strnatcasecmp($a['name'], $b['name']);
        }

        return $order === 'ASC' ? $ageA <=> $ageB : $ageB <=> $ageA;
    });

    return $set;
}
```

