2. Initialize a counter variable to keep track of the number of words containing the letter 'r'.
3. Loop through each word in the array and check if it contains the letter 'r'. If it does, increment the counter.
4. Return the value of the counter at the end of the loop.

Here's the implementation:

```javascript
function countWordsContaining(sentence, letter) {
  let counter = 0;
  const words = sentence.split(' ');

  for (let I = 0; I < words.length; i++) {
    const word = words[i];

    // Check if the word contains the given letter
    if (word.indexOf(letter) !== -1) {
      counter++;
    }
  }

  return counter;
}

