Here's how you can convert the Jest diff output to a JavaScript array:

 ```js
 // Input: Jest diff output
 const jestDiff = `- Array []
+ Array [
+ "",
+ Object {
+ "children": Array [
+ "dashboard",
+ Object {
+ "children": Array [
+ "settings",
+ Object {
+ "children": Array [
+ "",
+ Object {},
+ ],
+ },
+ ],
+ },
+ undefined,
+ "refetch",
+ ],
+ }
+ ]
+ ]`;

 // Convert to array using regex and string split
 const arr = jestDiff.split('\n')
   .filter(line => line.trim().length)
   .map(line => {
     const [sign, value] = line.split(' ').slice(-2);
     let result;

     if (value.startsWith('"')) {
       result = JSON.parse(value.slice(1, -1));
     } else {
       result = sign === '-' ? null : value;
     }

     return { sign, value, result };
   })
   .reduce((acc, cur) => {
     const { sign, result } = cur;

     if (Array.isArray(result)) {
       acc[cur.value] = result;
     } else {
       acc[cur.value] = result || {};
     }

     if (sign === '+') {
       acc[cur.value].children = acc[cur.value].children || [];
       acc[cur.value].children.push(...(Array.isArray(result) ? result : [result]));
     }

     return acc;
   }, {});

 console.log(arr);
